-- --- Billing and onboarding state --------------------------------------------
-- The sandbox never charges credits, but the rows must exist so the same code
-- paths run as for a real school.

INSERT INTO school_credits (school_id, balance) VALUES (v_school, 0);
INSERT INTO school_billing (school_id, billing_mode) VALUES (v_school, 'credits');

INSERT INTO school_complexity
    (school_id, student_count, teacher_count, campus_count, transport_enabled,
     bus_route_count, duties_enabled, cycle_days, accelerated_enabled,
     double_periods_enabled)
VALUES (v_school, 48, 14, 2, true, 2, true, 5, false, true);

INSERT INTO onboarding
    (school_id, step_school_details, step_campuses, step_billing, step_layout,
     step_teachers, step_students, step_rooms, step_subjects, step_transport,
     completed, completed_at)
VALUES (v_school, true, true, true, true, true, true, true, true, true, true, now());

-- --- Point the app at this school --------------------------------------------

UPDATE settings SET value = v_school::TEXT, updated_at = now()
WHERE key = 'sandbox_school_id';

RAISE NOTICE 'Sandbox school seeded: Westfield College (%)', v_school;

END $$;


-- ============================================================================
-- 005_class_group_slots.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 005 CLASS GROUP SLOTS
--
-- Layer 3 assigns each class group the period slots it occupies. Nothing in the
-- original schema held that: class_groups says a class exists, and
-- timetable_entries is only written at the very end, after validation passes.
-- Without this table the result of Layer 3 has nowhere to live while Layers 4
-- to 9 build on it.
--
-- One row per meeting, so a class that runs once a day for a 5-day cycle has 5
-- rows. Double periods are two rows with consecutive period_numbers, which is
-- what the "double periods occupy consecutive blocks" check in VALIDATION.md
-- needs in order to be checkable at all.
-- =============================================================================

CREATE TABLE IF NOT EXISTS class_group_slots (
    attempt_id      UUID    NOT NULL REFERENCES generation_attempts(id),
    class_group_id  UUID    NOT NULL REFERENCES class_groups(id),
    day_number      INTEGER NOT NULL,
    period_number   INTEGER NOT NULL,
    -- Resolved once the layout period is known. Nullable so Layer 3 can record
    -- the slot before Layer 4 attaches rooms.
    layout_period_id UUID   REFERENCES layout_periods(id),
    is_double_first BOOLEAN NOT NULL DEFAULT false,
    PRIMARY KEY (attempt_id, class_group_id, day_number, period_number)
);

CREATE INDEX IF NOT EXISTS idx_cgs_attempt_slot
    ON class_group_slots (attempt_id, day_number, period_number);

CREATE INDEX IF NOT EXISTS idx_cgs_group
    ON class_group_slots (class_group_id);

ALTER TABLE class_group_slots ENABLE ROW LEVEL SECURITY;

-- Scoped through the attempt to its school, the same way the allocation
-- registries are.
DROP POLICY IF EXISTS school_isolation ON class_group_slots;
CREATE POLICY school_isolation ON class_group_slots
    USING (EXISTS (
        SELECT 1 FROM generation_attempts ga
        JOIN timetables t ON t.id = ga.timetable_id
        WHERE ga.id = class_group_slots.attempt_id
          AND t.school_id = current_school_id()
    ));

DROP POLICY IF EXISTS dev_access ON class_group_slots;
CREATE POLICY dev_access ON class_group_slots
    USING ((SELECT role FROM users WHERE id = auth.uid()) = 'dev');


-- ============================================================================
-- 006_periods_per_cycle.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 006 PERIODS PER CYCLE
--
-- How many times a class meets per cycle is stated by the school, per subject
-- and year level. Nothing in the original schema held it, which left Layer 3
-- with no basis for deciding how many slots to allocate.
--
-- NULL means "use the school-wide default" (the default_periods_per_cycle
-- setting), so a school can set it once and override only where it differs.
-- =============================================================================

ALTER TABLE subject_settings
    ADD COLUMN IF NOT EXISTS periods_per_cycle INTEGER;

ALTER TABLE subject_settings
    DROP CONSTRAINT IF EXISTS subject_settings_periods_per_cycle_check;
ALTER TABLE subject_settings
    ADD CONSTRAINT subject_settings_periods_per_cycle_check
    CHECK (periods_per_cycle IS NULL
           OR (periods_per_cycle >= 1 AND periods_per_cycle <= 60));

INSERT INTO settings (key, value, category, description) VALUES
('default_periods_per_cycle', '5', 'timetable',
 'Times a class meets per cycle when the subject does not state its own')
ON CONFLICT (key) DO NOTHING;

-- Give the sandbox school a realistic spread so a generated timetable looks
-- like a real one rather than every subject meeting the same number of times.
UPDATE subject_settings SET periods_per_cycle = v.n
FROM (VALUES
    ('English', 5), ('Mathematics', 5), ('Science', 4), ('Computing', 3),
    ('History', 3), ('Geography', 3), ('PE', 2), ('Health', 1)
) AS v(subject, n)
WHERE subject_settings.subject = v.subject
  AND subject_settings.periods_per_cycle IS NULL
  AND subject_settings.school_id = (
      SELECT id FROM schools WHERE name = 'Westfield College' LIMIT 1);


-- ============================================================================
-- 007_periods_min_max.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 007 PERIODS PER CYCLE AS A RANGE
--
-- Supersedes the single periods_per_cycle added in 006. Schools state a minimum
-- and a maximum, so the allocator has room to move: it must give every class at
-- least the minimum, and may go up to the maximum where the timetable allows.
--
-- 006 is left in place rather than edited - it has already been applied, and a
-- migration that changes after running is a migration nobody can trust.
-- =============================================================================

ALTER TABLE subject_settings
    ADD COLUMN IF NOT EXISTS min_periods_per_cycle INTEGER,
    ADD COLUMN IF NOT EXISTS max_periods_per_cycle INTEGER;

-- Carry over anything 006 set: a fixed count becomes a range of one.
UPDATE subject_settings
SET min_periods_per_cycle = COALESCE(min_periods_per_cycle, periods_per_cycle),
    max_periods_per_cycle = COALESCE(max_periods_per_cycle, periods_per_cycle)
WHERE periods_per_cycle IS NOT NULL;

ALTER TABLE subject_settings DROP CONSTRAINT IF EXISTS subject_settings_periods_per_cycle_check;
ALTER TABLE subject_settings DROP COLUMN IF EXISTS periods_per_cycle;

ALTER TABLE subject_settings
    DROP CONSTRAINT IF EXISTS subject_settings_periods_range_check;
ALTER TABLE subject_settings
    ADD CONSTRAINT subject_settings_periods_range_check
    CHECK (
        (min_periods_per_cycle IS NULL OR
            (min_periods_per_cycle >= 1 AND min_periods_per_cycle <= 60))
        AND (max_periods_per_cycle IS NULL OR
            (max_periods_per_cycle >= 1 AND max_periods_per_cycle <= 60))
        AND (min_periods_per_cycle IS NULL OR max_periods_per_cycle IS NULL
             OR min_periods_per_cycle <= max_periods_per_cycle)
    );

DELETE FROM settings WHERE key = 'default_periods_per_cycle';

INSERT INTO settings (key, value, category, description) VALUES
('default_min_periods_per_cycle', '4', 'timetable',
 'Minimum times a class meets per cycle when the subject does not state its own'),
('default_max_periods_per_cycle', '5', 'timetable',
 'Maximum times a class meets per cycle when the subject does not state its own')
ON CONFLICT (key) DO NOTHING;

-- Sandbox: a realistic spread, with room to move on most subjects.
UPDATE subject_settings SET min_periods_per_cycle = v.lo, max_periods_per_cycle = v.hi
FROM (VALUES
    ('English', 4, 5), ('Mathematics', 4, 5), ('Science', 3, 4),
    ('Computing', 2, 3), ('History', 2, 3), ('Geography', 2, 3),
    ('PE', 1, 2), ('Health', 1, 1)
) AS v(subject, lo, hi)
WHERE subject_settings.subject = v.subject
  AND subject_settings.school_id = (
      SELECT id FROM schools WHERE name = 'Westfield College' LIMIT 1);


-- ============================================================================
-- 008_provider_models.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 008 NEW PROVIDER MODEL STRINGS
--
-- Adds settings rows for two providers that were not in the original design:
--
--   google    - Gemini on a Google AI Studio key. Gemini through OpenRouter is
--               billed (402 without credits); the same models on an AI Studio
--               key have a free tier.
--   anthropic - Claude, replacing Magistral for the allocation layers now that
--               Mistral's free tier is discontinued.
--
-- Assignments are NOT changed here. Point tasks at these with
-- `python admin.py set-model` once the corresponding key is stored, so the
-- database never references a model with no key behind it.
-- =============================================================================

INSERT INTO settings (key, value, category, description) VALUES
('model_gemini_free', 'gemini-2.5-flash', 'model',
 'Gemini on a Google AI Studio key (free tier)'),
('model_claude',      'claude-opus-5', 'model',
 'Claude for judgement work - interpretation, editing, validation'),
('model_claude_fast', 'claude-haiku-4-5', 'model',
 'Cheaper Claude for the bulk allocation layers')
ON CONFLICT (key) DO NOTHING;


-- ============================================================================
-- 009_job_queue.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 009 JOB QUEUE
--
-- A durable work queue in Postgres, replacing FastAPI background_tasks.
--
-- BUILD_ORDER specifies Redis + RQ. RQ forks workers with os.fork() and does
-- not run on Windows, and it is synchronous while the whole pipeline is async.
-- Postgres already stores every other piece of state, supports
-- FOR UPDATE SKIP LOCKED for safe concurrent claiming, and LISTEN/NOTIFY for
-- immediate pickup - so the queue costs no new infrastructure and survives a
-- restart, which background_tasks does not.
--
-- Separate from generation_jobs: that row tracks the progress of one attempt,
-- and the retry loop creates attempts as it goes. The queued unit of work is
-- the timetable, which exists before any attempt does.
-- =============================================================================

CREATE TABLE IF NOT EXISTS job_queue (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    job_type        TEXT NOT NULL,                      -- 'generate'
    school_id       UUID NOT NULL REFERENCES schools(id),
    timetable_id    UUID REFERENCES timetables(id),
    payload         JSONB NOT NULL DEFAULT '{}'::jsonb,

    -- Lower runs sooner. 10 = urgent (a blocked school), 100 = standard.
    priority        INTEGER NOT NULL DEFAULT 100,

    status          TEXT NOT NULL DEFAULT 'queued',
                    -- 'queued' | 'running' | 'complete' | 'failed' | 'cancelled'
    attempts        INTEGER NOT NULL DEFAULT 0,
    max_attempts    INTEGER NOT NULL DEFAULT 3,

    -- Set in the future to delay a retry (exponential backoff).
    available_at    TIMESTAMPTZ NOT NULL DEFAULT now(),

    claimed_at      TIMESTAMPTZ,
    claimed_by      TEXT,
    -- Updated while a job runs. A row whose heartbeat has gone stale is
    -- assumed dead and requeued, which is how a killed worker recovers.
    heartbeat_at    TIMESTAMPTZ,

    last_error      TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at    TIMESTAMPTZ,

    CONSTRAINT job_queue_status_check
        CHECK (status IN ('queued','running','complete','failed','cancelled'))
);

-- The claim query orders by priority then age, filtered to runnable rows.
CREATE INDEX IF NOT EXISTS idx_job_queue_claimable
    ON job_queue (priority, available_at, created_at)
    WHERE status = 'queued';

CREATE INDEX IF NOT EXISTS idx_job_queue_running
    ON job_queue (heartbeat_at) WHERE status = 'running';

CREATE INDEX IF NOT EXISTS idx_job_queue_school
    ON job_queue (school_id, created_at DESC);

-- One live job per timetable: a double-submitted generation would otherwise
-- run twice and charge twice.
CREATE UNIQUE INDEX IF NOT EXISTS idx_job_queue_one_live_per_timetable
    ON job_queue (timetable_id)
    WHERE status IN ('queued', 'running') AND timetable_id IS NOT NULL;

ALTER TABLE job_queue ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS school_isolation ON job_queue;
CREATE POLICY school_isolation ON job_queue
    USING (school_id = current_school_id());

DROP POLICY IF EXISTS dev_access ON job_queue;
CREATE POLICY dev_access ON job_queue
    USING ((SELECT role FROM users WHERE id = auth.uid()) = 'dev');

INSERT INTO settings (key, value, category, description) VALUES
('queue_heartbeat_seconds', '30', 'queue',
 'How often a running job refreshes its heartbeat'),
('queue_stale_seconds', '180', 'queue',
 'A running job with no heartbeat for this long is requeued'),
('queue_poll_seconds', '5', 'queue',
 'Fallback poll interval when no NOTIFY arrives'),
('queue_max_concurrent', '2', 'queue',
 'Generations one worker will run at once')
ON CONFLICT (key) DO NOTHING;


-- ============================================================================
-- 010_scheduled_jobs.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 010 SCHEDULED JOBS
--
-- Phase 10 adds three jobs that run on a clock rather than on a request:
-- daily interest accrual, monthly invoice generation, and daily invoice
-- enforcement (BILLING.md).
--
-- All three are destructive if they run twice. Interest accrued twice in a day
-- overcharges a school; a second invoice for the same month bills them again.
-- Several workers may be running, a process may restart just after a job fired,
-- and a dev may trigger one by hand from the portal - so "once per day" cannot
-- rely on the scheduler firing once.
--
-- This table is the guard. A job claims its slot with
-- INSERT ... ON CONFLICT DO NOTHING: exactly one caller inserts the row for a
-- given (job, date) and does the work, and every other caller sees zero rows
-- affected and stops. It doubles as the run history - what ran, when, and what
-- it did.
-- =============================================================================

CREATE TABLE IF NOT EXISTS scheduled_job_runs (
    job_name        TEXT NOT NULL,
    run_date        DATE NOT NULL,
    started_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at     TIMESTAMPTZ,
    status          TEXT NOT NULL DEFAULT 'running',
                    -- 'running' | 'complete' | 'failed'
    triggered_by    TEXT NOT NULL DEFAULT 'scheduler',
    summary         JSONB,
    error           TEXT,
    PRIMARY KEY (job_name, run_date)
);

-- The enforcement job reads every unpaid invoice past its due date daily.
CREATE INDEX IF NOT EXISTS idx_invoices_due
    ON invoices (due_date) WHERE status IN ('sent', 'overdue');

-- The interest job reads every outstanding charge daily.
CREATE INDEX IF NOT EXISTS idx_outstanding_open
    ON outstanding_charges (school_id) WHERE status = 'outstanding';

-- One invoice per school per billing period. The monthly job checks for an
-- existing invoice before creating one, but a unique index is what actually
-- prevents a double bill if two callers pass that check at the same moment.
CREATE UNIQUE INDEX IF NOT EXISTS idx_invoices_school_period
    ON invoices (school_id, period_start);

-- A PAYG charge is attempted once per generation. Retrying a failed charge
-- updates the existing row rather than writing a second one.
CREATE UNIQUE INDEX IF NOT EXISTS idx_payg_charge_timetable
    ON payg_charge_log (timetable_id);

-- Tracks the last day interest was applied to a charge, so accrual is correct
-- even if a day is missed (a deploy, an outage) - the job charges for the days
-- that actually elapsed rather than assuming exactly one.
ALTER TABLE outstanding_charges
    ADD COLUMN IF NOT EXISTS last_interest_date DATE;

-- Scheduled jobs run as the service role only; no school ever reads this table.
ALTER TABLE scheduled_job_runs ENABLE ROW LEVEL SECURITY;


-- ============================================================================
-- 011_rls_gaps.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 011 CLOSING THE RLS GAPS
--
-- Seventeen tables were left without Row Level Security by migration 002. They
-- are the ones with no school_id of their own - pipeline internals, the class
-- group link tables, and invoice lines - and 002 covers tables by name, so
-- anything not on its list was simply never protected.
--
-- This was not theoretical. An anonymous caller holding only the publishable
-- anon key - the key the frontend ships to every browser - could read them:
--
--     anon GET /rest/v1/generation_events -> HTTP 200, 1 row
--
-- They looked safe in testing only because the suites clean up after
-- themselves, so the tables are empty between runs. A real school generating a
-- real timetable fills them with the mapping of which student sits in which
-- class at which time.
--
-- check_rls_leak.py reported PASS throughout, because it walks a hand-written
-- list of table names that did not include any of these. It now enumerates the
-- tables from the database instead.
--
-- None of these tables has a school_id column, so each is scoped through the
-- row that owns it, the way 002 already handles timetable_entries.
-- =============================================================================

-- --- Scoped through the generation attempt ----------------------------------
-- attempt -> timetable -> school. One predicate, twelve tables.

DO $$
DECLARE
    t TEXT;
    tables TEXT[] := ARRAY[
        'allocation_registry_students', 'allocation_registry_teachers',
        'allocation_registry_rooms', 'allocation_registry_buses',
        'allocation_registry_duties', 'allocation_registry_duty_counts',
        'class_consistency_registry', 'generation_events', 'generation_jobs',
        'partial_solutions', 'pipeline_state', 'validation_results'
    ];
    predicate TEXT := $p$
        attempt_id IN (
            SELECT ga.id FROM generation_attempts ga
            JOIN timetables tt ON tt.id = ga.timetable_id
            WHERE tt.school_id = current_school_id())
    $p$;
BEGIN
    FOREACH t IN ARRAY tables LOOP
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);

        EXECUTE format('DROP POLICY IF EXISTS school_isolation ON %I', t);
        EXECUTE format(
            'CREATE POLICY school_isolation ON %I FOR ALL USING (%s) '
            'WITH CHECK (%s)', t, predicate, predicate);

        EXECUTE format('DROP POLICY IF EXISTS dev_access ON %I', t);
        EXECUTE format(
            'CREATE POLICY dev_access ON %I FOR ALL USING (is_dev()) '
            'WITH CHECK (is_dev())', t);
    END LOOP;
END $$;


-- --- Scoped through their own parent ----------------------------------------

-- class_groups already carries school_id.
ALTER TABLE class_group_students ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS school_isolation ON class_group_students;
CREATE POLICY school_isolation ON class_group_students
    FOR ALL
    USING (class_group_id IN (
        SELECT id FROM class_groups WHERE school_id = current_school_id()))
    WITH CHECK (class_group_id IN (
        SELECT id FROM class_groups WHERE school_id = current_school_id()));
DROP POLICY IF EXISTS dev_access ON class_group_students;
CREATE POLICY dev_access ON class_group_students
    FOR ALL USING (is_dev()) WITH CHECK (is_dev());

ALTER TABLE class_group_explicit_students ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS school_isolation ON class_group_explicit_students;
CREATE POLICY school_isolation ON class_group_explicit_students
    FOR ALL
    USING (class_group_def_id IN (
        SELECT id FROM class_group_definitions
        WHERE school_id = current_school_id()))
    WITH CHECK (class_group_def_id IN (
        SELECT id FROM class_group_definitions
        WHERE school_id = current_school_id()));
DROP POLICY IF EXISTS dev_access ON class_group_explicit_students;
CREATE POLICY dev_access ON class_group_explicit_students
    FOR ALL USING (is_dev()) WITH CHECK (is_dev());

ALTER TABLE class_group_rules ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS school_isolation ON class_group_rules;
CREATE POLICY school_isolation ON class_group_rules
    FOR ALL
    USING (class_group_def_id IN (
        SELECT id FROM class_group_definitions
        WHERE school_id = current_school_id()))
    WITH CHECK (class_group_def_id IN (
        SELECT id FROM class_group_definitions
        WHERE school_id = current_school_id()));
DROP POLICY IF EXISTS dev_access ON class_group_rules;
CREATE POLICY dev_access ON class_group_rules
    FOR ALL USING (is_dev()) WITH CHECK (is_dev());

-- A school's billing detail, line by line.
ALTER TABLE invoice_line_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS school_isolation ON invoice_line_items;
CREATE POLICY school_isolation ON invoice_line_items
    FOR ALL
    USING (invoice_id IN (
        SELECT id FROM invoices WHERE school_id = current_school_id()))
    WITH CHECK (invoice_id IN (
        SELECT id FROM invoices WHERE school_id = current_school_id()));
DROP POLICY IF EXISTS dev_access ON invoice_line_items;
CREATE POLICY dev_access ON invoice_line_items
    FOR ALL USING (is_dev()) WITH CHECK (is_dev());


-- --- Internal ----------------------------------------------------------------
-- The migration ledger tells an attacker exactly which schema version is
-- deployed. No client has any reason to read it: RLS on, no policy, so only the
-- service role and the direct Postgres connection can see it.

ALTER TABLE schema_migrations ENABLE ROW LEVEL SECURITY;


-- --- Indexes supporting the new predicates -----------------------------------
-- Every policy above filters on the parent key, so each needs an index on it or
-- RLS turns cheap lookups into sequential scans on the biggest tables in the
-- schema.

CREATE INDEX IF NOT EXISTS idx_alloc_students_attempt
    ON allocation_registry_students (attempt_id);
CREATE INDEX IF NOT EXISTS idx_alloc_teachers_attempt
    ON allocation_registry_teachers (attempt_id);
CREATE INDEX IF NOT EXISTS idx_alloc_rooms_attempt
    ON allocation_registry_rooms (attempt_id);
CREATE INDEX IF NOT EXISTS idx_class_group_students_group
    ON class_group_students (class_group_id);
CREATE INDEX IF NOT EXISTS idx_invoice_lines_invoice
    ON invoice_line_items (invoice_id);


-- ============================================================================
-- 012_support_notes.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 012 SUPPORT TICKET HANDLING
--
-- SUPPORT.md gives the dev portal two things the schema had no room for:
-- internal notes ("not visible to school") and a record of who resolved a
-- ticket. Without somewhere to put them, "add an internal note" would have to
-- be appended to the body the school can read - which is the opposite of what
-- internal means.
-- =============================================================================

ALTER TABLE support_tickets
    ADD COLUMN IF NOT EXISTS internal_notes TEXT,
    ADD COLUMN IF NOT EXISTS resolved_by    TEXT,
    ADD COLUMN IF NOT EXISTS first_response_at TIMESTAMPTZ;

-- The dev queue lists open tickets worst-first, and a school lists its own.
CREATE INDEX IF NOT EXISTS idx_tickets_queue
    ON support_tickets (status, priority, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tickets_school
    ON support_tickets (school_id, created_at DESC);

-- A school reads its own tickets through the API, never through the Supabase
-- client, and internal_notes must never reach it either way. The table already
-- has school_isolation from 002; this makes the intent explicit in the schema.
COMMENT ON COLUMN support_tickets.internal_notes IS
    'Dev-only. Never returned by a school-facing endpoint.';


-- --- Export templates --------------------------------------------------------
-- Two schools can both have a template called "Sentral", but one school should
-- not end up with two of them - the dropdown on the export page would show the
-- same name twice with no way to tell them apart.

CREATE UNIQUE INDEX IF NOT EXISTS idx_export_template_name
    ON csv_output_templates (school_id, lower(name));


-- ============================================================================
-- 013_sandbox_run.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 013 THE FREE SANDBOX RUN
--
-- `onboarding` already had sandbox_used and sandbox_used_at from migration 001,
-- but nothing ever set them: the free run the marketing site promises was never
-- built. What was missing is somewhere to record *which* timetable a school was
-- given, because the run happens on the sandbox school's data, not theirs.
--
-- That is the whole design. Copying Westfield College's 48 students into a real
-- school to demonstrate the product would leave them deleting sample data
-- before they could start, and a school that abandoned setup would be left
-- with a fake roll. So the generation runs on the sandbox school and the
-- requesting school is granted read access to that one timetable - recorded
-- here, and nowhere else.
-- =============================================================================

ALTER TABLE onboarding
    ADD COLUMN IF NOT EXISTS sandbox_timetable_id UUID REFERENCES timetables(id);

COMMENT ON COLUMN onboarding.sandbox_timetable_id IS
    'The one sandbox-school timetable this school may read. Read-only: it can '
    'never be published, edited or exported as their own.';

-- The read allowance is checked on every output request for a sandbox viewer,
-- so it needs to be a lookup rather than a scan.
CREATE INDEX IF NOT EXISTS idx_onboarding_sandbox
    ON onboarding (sandbox_timetable_id)
    WHERE sandbox_timetable_id IS NOT NULL;

-- A sample timetable is marked in its own notes, so it is obvious in the
-- sandbox school's history which runs were demonstrations and for whom.
-- No new column: timetable_versions.notes already exists for exactly this.


-- ============================================================================
-- 014_sse_settings.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 014 LIVE PROGRESS STREAM SETTINGS
--
-- The SSE progress stream polled every second and ran until its job reached a
-- terminal state. If that never happened - a worker killed mid-run, a job row
-- removed - it polled forever for as long as the tab stayed open.
--
-- Both numbers belong in settings rather than in the code: the poll interval is
-- the main cost of watching a generation, and the cap is the kind of thing that
-- wants changing under load without a redeploy.
-- =============================================================================

INSERT INTO settings (key, value, category, description) VALUES
('sse_max_seconds',  '1800', 'timetable',
 'Maximum lifetime of one live progress stream before it closes and asks the page to reconnect'),
('sse_poll_seconds', '1',    'timetable',
 'How often a live progress stream checks for new events')
ON CONFLICT (key) DO NOTHING;


-- ============================================================================
-- 015_email_log.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 015 EMAIL LOG
--
-- Every email attempted, whether or not it was sent.
--
-- The question this exists to answer is "did the school get told?" - the first
-- one asked when a school says they were charged, or blocked, without warning.
-- Without a record, the honest answer is "probably".
--
-- 'skipped' is a first-class status, not an error: with no provider key
-- configured the template is still rendered and the intent recorded, so the
-- whole path is exercised and testable before Resend exists.
-- =============================================================================

CREATE TABLE IF NOT EXISTS email_log (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    school_id       UUID REFERENCES schools(id),
    user_id         UUID REFERENCES users(id),
    recipient       TEXT NOT NULL,
    template_name   TEXT NOT NULL,
    subject         TEXT NOT NULL,
    status          TEXT NOT NULL,
                    -- 'sent' | 'skipped' | 'failed'
    error           TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- The dev portal reads this newest-first, and per school when investigating one.
CREATE INDEX IF NOT EXISTS idx_email_log_recent
    ON email_log (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_email_log_school
    ON email_log (school_id, created_at DESC);

-- Recipient addresses across every school. A school has no business reading
-- this through the Supabase client; the dev portal reads it as the service
-- role. RLS on, no policy: deny all.
ALTER TABLE email_log ENABLE ROW LEVEL SECURITY;


-- ============================================================================
-- 016_email_log_detach.sql
-- ============================================================================

-- =============================================================================
-- KLASSER AI - 016 THE EMAIL LOG MUST NOT PIN ITS SUBJECTS
--
-- Migration 015 gave email_log plain foreign keys to users and schools. That
-- made the log block deletion of the very rows it describes: removing a user
-- failed with a foreign key violation because an email had once been sent to
-- them.
--
-- Both halves of that are wrong. A record of "we emailed this person" should
-- not stop the person being deleted, and it should not disappear when they are
-- - the whole reason it exists is to answer "was the school told?" after the
-- fact, including about people who have since left.
--
-- ON DELETE SET NULL keeps the row, the address, the template and the outcome,
-- and lets the user or school go. The recipient column is plain text and is
-- never nulled, so the record stays meaningful.
-- =============================================================================

ALTER TABLE email_log DROP CONSTRAINT IF EXISTS email_log_user_id_fkey;
ALTER TABLE email_log DROP CONSTRAINT IF EXISTS email_log_school_id_fkey;

ALTER TABLE email_log
    ADD CONSTRAINT email_log_user_id_fkey
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL;

ALTER TABLE email_log
    ADD CONSTRAINT email_log_school_id_fkey
    FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE SET NULL;


-- =============================================================================
-- Migration bookkeeping
--
-- Records what migrate.py would have recorded, with the same checksums, so this
-- file and the incremental path leave the database in the same state.
-- =============================================================================

CREATE TABLE IF NOT EXISTS schema_migrations (
    filename    TEXT PRIMARY KEY,
    checksum    TEXT NOT NULL,
    applied_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

